import json, os, re, time, urllib.request
from datetime import datetime, timezone
raw = os.environ["BLAND_API_KEY"].strip()
if raw.startswith("{"):
    p = json.loads(raw); raw = next((p[k] for k in ("api_key", "key", "value") if p.get(k)), raw)
AGENT = "+15095611012"
from datetime import timedelta
END_UTC = (datetime.now(timezone.utc) + timedelta(days=1)).replace(hour=12, minute=30, second=0)
FILLER = re.compile(r"one moment while i check|let me check that for you", re.I)
seen_failures = set()
seen_convos = set()

def get(path):
    req = urllib.request.Request("https://api.bland.ai" + path, headers={"Authorization": raw, "User-Agent": "mybcat-cli"})
    with urllib.request.urlopen(req, timeout=90) as r:
        return json.loads(r.read().decode())

cycle = 0
while datetime.now(timezone.utc) < END_UTC:
    cycle += 1
    try:
        listing = get("/v1/sms/conversations?limit=100")
        rows = listing if isinstance(listing, list) else (listing.get("data") or listing.get("conversations") or [])
        todays = []
        for c in rows:
            if not isinstance(c, dict):
                continue
            if str(c.get("agent_number", "")) != AGENT:
                continue
            ts = str(c.get("updated_at", c.get("created_at", "")))
            if ts[:10] == datetime.now(timezone.utc).strftime("%Y-%m-%d"):
                todays.append(str(c.get("conversation_id", c.get("id", ""))))
        new_failures = []
        for cid in todays:
            if not cid or cid in seen_failures:
                continue
            seen_convos.add(cid)
            try:
                d = get("/v1/sms/conversations/%s" % cid).get("data") or {}
            except Exception:
                continue
            msgs = d.get("messages") or []
            agent_msgs = [m for m in msgs if str(m.get("sender", m.get("role", ""))).upper() in ("AGENT", "ASSISTANT")]
            if not agent_msgs:
                continue
            last_agent = agent_msgs[-1]
            if not FILLER.search(str(last_agent.get("message", last_agent.get("content", "")))):
                continue
            last_ts = str(last_agent.get("created_at", ""))
            try:
                age = (datetime.now(timezone.utc) - datetime.fromisoformat(last_ts.replace("Z", "+00:00"))).total_seconds()
            except Exception:
                age = 0
            if age > 300:
                seen_failures.add(cid)
                new_failures.append(cid)
        now = datetime.now(timezone.utc).strftime("%H:%M")
        print("CYCLE %d %sZ convos_today=%d failures_total=%d new=%s" % (cycle, now, len(seen_convos), len(seen_failures), [c[-6:] for c in new_failures] or "none"), flush=True)
        if len(seen_failures) >= 2:
            print("ESCALATE: %d promise-then-silence conversations detected (criterion: 2). ids(last6)=%s" % (len(seen_failures), sorted(c[-6:] for c in seen_failures)), flush=True)
            raise SystemExit(1)
    except SystemExit:
        raise
    except Exception as e:
        print("CYCLE %d MONITOR_ERROR %s: %s" % (cycle, type(e).__name__, str(e)[:150]), flush=True)
        if cycle == 1:
            print("MONITOR_BROKEN on first cycle - API shape mismatch; needs orchestrator attention", flush=True)
            raise SystemExit(3)
    time.sleep(900)
print("MONITOR_COMPLETE failures_total=%d convos_today=%d" % (len(seen_failures), len(seen_convos)), flush=True)
